-- Full migration bookkeeping is separate from authentication and application views.
CREATE TABLE legacy_record_snapshots (source_system TEXT NOT NULL, source_table TEXT NOT NULL, source_id TEXT NOT NULL, source_hash TEXT NOT NULL, fields_json TEXT NOT NULL CHECK(json_valid(fields_json)), target_table TEXT NOT NULL, target_id TEXT NOT NULL, target_hash TEXT NOT NULL, manifest_id TEXT NOT NULL REFERENCES import_manifests(id), source_created_at TEXT, source_updated_at TEXT, present_in_source INTEGER NOT NULL DEFAULT 1 CHECK(present_in_source IN (0,1)), PRIMARY KEY(source_system,source_table,source_id));
CREATE TABLE legacy_auth_roster (source_auth_id TEXT PRIMARY KEY, source_user_id TEXT, source_email TEXT NOT NULL, source_status TEXT NOT NULL, source_active INTEGER NOT NULL CHECK(source_active IN (0,1)), verified_link INTEGER NOT NULL DEFAULT 0 CHECK(verified_link IN (0,1)), metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json)), manifest_id TEXT NOT NULL REFERENCES import_manifests(id));
CREATE TABLE import_dispositions (id TEXT PRIMARY KEY, manifest_id TEXT NOT NULL REFERENCES import_manifests(id), source_table TEXT, source_id TEXT, code TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','reviewed')), note TEXT, created_at TEXT NOT NULL);
CREATE TABLE import_write_guards (id TEXT PRIMARY KEY, valid INTEGER NOT NULL CHECK(valid=1));
